body:
Ok I actually got it working with:

```javascript
search.addWidget(
	instantsearch.widgets.rangeSlider({
		container: '#priceRange',
		attributeName: 'lp',
		tooltips: {
			format: function(rawValue) {
				return '£' + Math.round(rawValue).toLocaleString();
			}
		},
		pips: {
			mode: 'positions',
			values: [0,50,100],
			density: 3,
			format: wNumb({
				decimals: 0,
				prefix: '£'
			})
		},
		templates: {
			header: 'Price Range'
		},
		cssClasses: {
			root: 'panel panel-default quick-search-facet-panel',
			header: 'panel-heading',
			body: 'panel-body'
		}
	})
);
```
